const email = items[0].json;
const from = email.from || '';
const subject = email.subject || '';
const text = email.text || '';

let category = 'other';

if (from.includes('no-reply') || subject.toLowerCase().includes('newsletter')) category = 'newsletter';
if (subject.toLowerCase().includes('invoice') || subject.toLowerCase().includes('payment')) category = 'important';
if (subject.toLowerCase().includes('win money') || text.toLowerCase().includes('lottery')) category = 'spam';

return [{ json: { from, subject, category } }];
